WITH unpacked AS (SELECT id, service, host, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT id, service, duration_sec, retry_count, AVG(retry_count) OVER (PARTITION BY host ORDER BY retry_count, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_retry_count, MAX(retry_count) OVER (PARTITION BY host ORDER BY retry_count, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_retry_count, COUNT(retry_count) OVER (PARTITION BY host ORDER BY retry_count, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_retry_count, AVG(duration_sec) OVER (ORDER BY duration_sec, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_6_prior FROM unpacked
